const pixels={"kas2_bldg_platform_edge":{"size":128,"pixels":""},"kas2_metals":{"size":128,"pixels":""},"kas2-suspension-deck":{"size":256,"pixels":""},"kas2-suspension-details":{"size":512,"pixels":""}};
// Suspension ropes and timber use the BF1 atlas referenced by their authored UVs.
