const cache=new Map();
export function bridgeTexture(name){if(cache.has(name))return cache.get(name);const source=pixels[name],bytes=Uint8Array.from(atob(source.pixels),c=>c.charCodeAt(0)),texture=new T.DataTexture(bytes,source.size,source.size,T.RGBAFormat);texture.colorSpace=T.SRGBColorSpace;texture.wrapS=texture.wrapT=T.RepeatWrapping;texture.magFilter=T.LinearFilter;texture.minFilter=T.LinearMipmapLinearFilter;texture.generateMipmaps=true;texture.flipY=true;texture.needsUpdate=true;cache.set(name,texture);return texture;}
